/* 07. THX Section End */

/* 08. Pop-Up Section Start */
.disc-modal { position: fixed;
  inset: 0;
  z-index: 100001;
  display: none; }
.disc-modal.is-open { display: block; }
.disc-modal__overlay { position: absolute;
  inset: 0;
  background: rgba(13,13,13,.65); }
.disc-modal__dialog { position: relative;
  width: min(980px, calc(100% - 32px));
  max-height: min(90vh, 820px);
  margin: 5vh auto;
  border-radius: 16px;
  background: #fff;
