/* Smoke test: render, data, drag, flow, score — via CDP */
const { execFileSync, spawn } = require("node:child_process");
const fs = require("node:fs");
const net = require("node:net");

const PAGE = "file:///home/dp/MyProjects/disc/.tmpwork/disc-pi-1g70bbb8/run/index.html";
const PORT = 9333;

function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

async function getJson(path) {
  const http = require("node:http");
  return new Promise((resolve, reject) => {
    http.get({ host: "127.0.0.1", port: PORT, path }, (res) => {
      let b = "";
      res.on("data", (c) => (b += c));
      res.on("end", () => resolve(JSON.parse(b)));
    }).on("error", reject);
  });
}

class Tab {
  constructor(wsUrl) {
    this.ws = new WebSocket(wsUrl);
    this.id = 0;
    this.pending = new Map();
    this.events = [];
    this.exceptions = [];
    this.consoleErrors = [];
    this.networkToExternal = 0;
  }
  ready() { return new Promise((r) => (this.ws.onopen = r)); }
  send(method, params = {}) {
    const id = ++this.id;
    this.ws.send(JSON.stringify({ id, method, params }));
    return new Promise((r) => this.pending.set(id, r));
  }
  async eval(expression) {
    const r = await this.send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
    if (r.exceptionDetails) {
      throw new Error("EVAL ERROR: " + JSON.stringify(r.exceptionDetails.exception?.description || r.exceptionDetails.text));
    }
    return r.result.value;
  }
  onmessage(ev) {
    const msg = JSON.parse(ev.data);
    if (msg.id && this.pending.has(msg.id)) { this.pending.get(msg.id)(msg.result); this.pending.delete(msg.id); return; }
    if (msg.method) {
      if (msg.method === "Runtime.exceptionThrown") this.exceptions.push(JSON.stringify(msg.params.exceptionDetails));
      if (msg.method === "Runtime.consoleAPICalled" && msg.params.type === "error") this.consoleErrors.push(JSON.stringify(msg.params.args));
      if (msg.method === "Network.requestWillBeSent") {
        if (!msg.params.request.url.startsWith("file://")) this.networkToExternal += 1;
      }
    }
  }
}

(async () => {
  const chrome = spawn("/usr/bin/google-chrome", [
    "--headless=new", "--no-sandbox", "--disable-gpu", "--disable-dev-shm-usage",
    `--remote-debugging-port=${PORT}`, "--user-data-dir=/tmp/chrome-disc-test",
    "about:blank"
  ], { stdio: "ignore" });

  let target = null;
  for (let i = 0; i < 40 && !target; i++) {
    await sleep(250);
    try {
      const list = await getJson("/json/list");
      target = list.find((t) => t.type === "page");
    } catch (_) {}
  }
  if (!target) throw new Error("no chrome target");

  const tab = new Tab(target.webSocketDebuggerUrl);
  tab.ws.onmessage = (e) => tab.onmessage(e);
  await tab.ready();
  await tab.send("Runtime.enable");
  await tab.send("Network.enable");
  await tab.send("Log.enable");
  await tab.send("Page.navigate", { url: PAGE });
  await sleep(800);

  let pass = 0, fail = 0;
  const check = (name, cond, extra = "") => {
    if (cond) { pass++; console.log("  ok  -", name); }
    else { fail++; console.log("  FAIL-", name, extra); }
  };

  console.log("== render smoke ==");
  check("lists: 24", await tab.eval("document.querySelectorAll('.disc-list').length") === 24);
  check("items: 96", await tab.eval("document.querySelectorAll('.disc-item').length") === 96);
  check("no uncaught JS", tab.exceptions.length === 0, JSON.stringify(tab.exceptions));
  check("no console.error", tab.consoleErrors.length === 0, JSON.stringify(tab.consoleErrors));

  console.log("== data integrity (page vs reference) ==");
  const pageData = await tab.eval(`JSON.stringify(Array.from(document.querySelectorAll('.disc-list')).map(ul => Array.from(ul.children).map(li => [li.dataset.type, li.textContent.replace(/\\s+$/, '')])))`);
  const ref = JSON.parse(fs.readFileSync("/tmp/items.json", "utf8"));
  const refLists = [];
  for (let i = 0; i < 96; i += 4) {
    const l = [];
    for (let k = 0; k < 4; k++) l.push([ref[i + k].type, ref[i + k].text]);
    refLists.push(l);
  }
  const pd = JSON.parse(pageData);
  let same = pd.length === refLists.length;
  if (same) for (let i = 0; i < 24; i++) {
    if (JSON.stringify(pd[i]) !== JSON.stringify(refLists[i])) { same = false; break; }
  }
  check("all (type,text) pairs byte-equal incl. order", same);
  check("latin-c quirk preserved (Экспресcivalny with latin c)",
    await tab.eval(`Array.from(document.querySelectorAll('.disc-item')).some(li => /\\d*[\\x00-\\x7f]/.test('') || [String.fromCharCode(69+0x410-410)].length === 1 && li.textContent.includes('Экспрес' + String.fromCharCode(99) + 'ивный'))`));

  console.log("== flow ==");
  check("start screen visible", await tab.eval(`document.getElementById('screenStart').classList.contains('is-active')`));
  await tab.eval(`document.getElementById('btnStart').click(); true`);
  check("test screen visible", await tab.eval(`document.getElementById('screenTest').classList.contains('is-active')`));
  check("prev disabled on step 1", await tab.eval(`document.getElementById('btnPrev').disabled === true`));
  check("next visible on step 1", await tab.eval(`!document.getElementById('btnNext').hidden`));
  check("finish hidden on step 1", await tab.eval(`document.getElementById('btnFinish').hidden`));
  check("progress 12.5%", await tab.eval(`Math.round(parseFloat(document.getElementById('discProgress').style.width) * 10) / 10`) === 12.5);

  console.log("== drag & drop (pointer events) ==");
  const dragResult = await tab.eval(`(() => {
    const ul = document.querySelector('.disc-list');
    const items = Array.from(ul.children);
    const src = items[1];
    const r = src.getBoundingClientRect();
    const x = r.left + r.width / 2;
    const yStart = r.top + r.height / 2;
    const targetY = items[2].getBoundingClientRect().bottom + 5;
    const opts = (x, y) => ({ bubbles: true, cancelable: true, pointerId: 1, pointerType: 'mouse', isPrimary: true, clientX: x, clientY: y, buttons: 1 });
    src.dispatchEvent(new PointerEvent('pointerdown', opts(x, yStart)));
    src.dispatchEvent(new PointerEvent('pointermove', opts(x, yStart + 8)));
    for (let y = yStart + 8; y <= targetY; y += 15) src.dispatchEvent(new PointerEvent('pointermove', opts(x, y)));
    src.dispatchEvent(new PointerEvent('pointermove', opts(x, targetY)));
    const mid = Array.from(ul.children).map(li => li.dataset.type).join(',');
    src.dispatchEvent(new PointerEvent('pointerup', opts(x, targetY)));
    return Array.from(ul.children).map(li => li.dataset.type).join(',') + '|' + mid;
  })()`);
  console.log("  drag result:", dragResult);
  check("order changed by drag", dragResult.split('|')[0] === 'i,d,s,c');

  console.log("== navigation ==");
  await tab.eval(`document.querySelectorAll('[data-step-btn]')[3].click(); true`);
  check("tab jump to step 4", await tab.eval(`document.querySelector('[data-step-pane="3"]').classList.contains('is-active')`));
  await tab.eval(`document.getElementById('btnPrev').click(); true`);
  check("prev works", await tab.eval(`document.querySelector('[data-step-pane="2"]').classList.contains('is-active')`));
  for (let i = 2; i < 8; i++) await tab.eval(`document.getElementById('btnNext').click(); true`);
  check("finish visible on step 8", await tab.eval(`!document.getElementById('btnFinish').hidden`));
  check("next hidden on step 8", await tab.eval(`document.getElementById('btnNext').hidden`));
  check("progress 100%", await tab.eval(`parseFloat(document.getElementById('discProgress').style.width)`) === 100);

  console.log("== finish + score ==");
  // expected score: reference initial order, list0 now [i,d,s,c] (was [i,c,d,s])
  const score = (lists) => {
    const s = { d: 0, i: 0, s: 0, c: 0 };
    lists.forEach((l) => { s[l[0][0]] += 1; s[l[3][0]] -= 1; });
    return s;
  };
  const mutated = refLists.map((l) => l.slice());
  mutated[0] = [["i", "Экспресcивный"], ["d", "Волевой"], ["s", "Осторожный"], ["c", "Покладистый"]];
  const expected = score(mutated);
  const shown = await tab.eval(`document.getElementById('resultScore').textContent`);
  console.log("  expected:", `D:${expected.d}, I:${expected.i}, S:${expected.s}, C:${expected.c}`, "shown:", shown);
  check("result screen", await tab.eval(`document.getElementById('screenResult').classList.contains('is-active')`));
  check("score matches independent computation", shown === `D:${expected.d}, I:${expected.i}, S:${expected.s}, C:${expected.c}`);

  console.log("== restart ==");
  await tab.eval(`document.getElementById('btnRestart').click(); true`);
  check("back to test", await tab.eval(`document.getElementById('screenTest').classList.contains('is-active')`));
  check("orders reset to initial", await tab.eval(`Array.from(document.querySelectorAll('.disc-list')[0].children).map(li => li.dataset.type).join(',')`) === 'i,c,d,s');
  check("step reset to 1", await tab.eval(`document.querySelector('[data-step-pane="0"]').classList.contains('is-active')`));

  console.log("== external network ==");
  check("0 external requests during whole session", tab.networkToExternal === 0, String(tab.networkToExternal));

  console.log(`\nRESULT: ${pass} passed, ${fail} failed`);
  chrome.kill("SIGKILL");
  process.exit(fail ? 1 : 0);
})().catch((e) => { console.error("HARNESS ERROR:", e.message); process.exit(2); });

